type MdbRedisClusterConfig struct {
	// Allows some data to be lost in favor of faster switchover/restart by RDSync.
	AllowDataLoss *bool `pulumi:"allowDataLoss"`
	// Time to start the daily backup, in the UTC timezone.
	BackupWindowStart *MdbRedisClusterConfigBackupWindowStart `pulumi:"backupWindowStart"`
	// Normal clients output buffer limits. See [redis config file](https://github.com/redis/redis/blob/6.2/redis.conf#L1841).
	ClientOutputBufferLimitNormal *string `pulumi:"clientOutputBufferLimitNormal"`
	// Pubsub clients output buffer limits. See [redis config file](https://github.com/redis/redis/blob/6.2/redis.conf#L1843).
	ClientOutputBufferLimitPubsub *string `pulumi:"clientOutputBufferLimitPubsub"`
	// Permits Pub/Sub shard operations when cluster is down.
	ClusterAllowPubsubshardWhenDown *bool `pulumi:"clusterAllowPubsubshardWhenDown"`
	// Allows read operations when cluster is down.
	ClusterAllowReadsWhenDown *bool `pulumi:"clusterAllowReadsWhenDown"`
	// Controls whether all hash slots must be covered by nodes.
	ClusterRequireFullCoverage *bool `pulumi:"clusterRequireFullCoverage"`
	// Number of databases (changing requires redis-server restart).
	Databases *int `pulumi:"databases"`
	// Allow Redis to use io-threads.
	IoThreadsAllowed *bool `pulumi:"ioThreadsAllowed"`
	// The time, in minutes, that must elapse in order for the key counter to be divided by two (or decremented if it has a value less <= 10).
	LfuDecayTime *int `pulumi:"lfuDecayTime"`
	// Determines how the frequency counter represents key hits.
	LfuLogFactor *int `pulumi:"lfuLogFactor"`
	// Maximum time in milliseconds for Lua scripts.
	LuaTimeLimit *int `pulumi:"luaTimeLimit"`
	// Redis maxmemory usage in percent
	MaxmemoryPercent *int `pulumi:"maxmemoryPercent"`
	// Redis key eviction policy for a dataset that reaches maximum memory. Can be any of the listed in [the official RedisDB documentation](https://docs.redislabs.com/latest/rs/administering/database-operations/eviction-policy/).
	MaxmemoryPolicy *string `pulumi:"maxmemoryPolicy"`
	// Select the events that Redis will notify among a set of classes.
	NotifyKeyspaceEvents *string `pulumi:"notifyKeyspaceEvents"`
	// Password for the Redis cluster.
	Password string `pulumi:"password"`
	// Replication backlog size as a percentage of flavor maxmemory.
	ReplBacklogSizePercent *int `pulumi:"replBacklogSizePercent"`
	// Log slow queries below this number in microseconds.
	SlowlogLogSlowerThan *int `pulumi:"slowlogLogSlowerThan"`
	// Slow queries log length.
	SlowlogMaxLen *int `pulumi:"slowlogMaxLen"`
	// Close the connection after a client is idle for N seconds.
	Timeout *int `pulumi:"timeout"`
	// Allows to turn before switchover in RDSync.
	TurnBeforeSwitchover *bool `pulumi:"turnBeforeSwitchover"`
	// Use JIT for lua scripts and functions.
	UseLuajit *bool `pulumi:"useLuajit"`
	// Version of Redis.
	Version string `pulumi:"version"`
	// Controls max number of entries in zset before conversion from memory-efficient listpack to CPU-efficient hash table and skiplist
	ZsetMaxListpackEntries *int `pulumi:"zsetMaxListpackEntries"`
}

